package com.clavis.reader;
import android.app.*;import android.app.job.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.zip.*;
final class CatalogDownloads {
 static final int JOB=7319;static final long MAX_BYTES=4L*1024*1024*1024;
 static synchronized JSONObject records(Context c){try{return new JSONObject(c.getSharedPreferences("catalog_downloads",0).getString("jobs","{}"));}catch(Exception e){return new JSONObject();}}
 static synchronized void record(Context c,long id,JSONObject item){try{JSONObject all=records(c);all.put(Long.toString(id),item);c.getSharedPreferences("catalog_downloads",0).edit().putString("jobs",all.toString()).apply();}catch(Exception e){throw new IllegalStateException(e);}}
 static boolean imported(Context c,String id){JSONObject all=records(c);for(Iterator<String> keys=all.keys();keys.hasNext();){JSONObject entry=all.optJSONObject(keys.next());if(entry!=null&&entry.optString("id").equals(id)&&entry.optBoolean("imported"))for(Book book:Store.load(c))if(book.uri.equals(entry.optString("uri")))return true;}return false;}
 static void offer(MainActivity a,JSONObject item){if(item.optBoolean("pendingAudio")){ProgressDialog progress=new ProgressDialog(a);progress.setMessage("Loading download details…");progress.setCancelable(true);progress.show();CatalogRepository.worker.execute(()->{try{JSONObject resolved=CatalogRepository.audio(new JSONObject(CatalogRepository.get(item.getString("evidence"))),item.optInt("rank"));a.handler.post(()->{boolean active=progress.isShowing();if(!a.isFinishing()&&!a.isDestroyed()){progress.dismiss();if(active){if(resolved==null)error(a,"This recording has no downloadable MP3 archive.");else offer(a,resolved);}}});}catch(Exception e){a.handler.post(()->{boolean active=progress.isShowing();if(!a.isFinishing()&&!a.isDestroyed()){progress.dismiss();if(active)error(a,"Could not load download details. Please try again.");}});}});return;}JSONObject all=records(a);for(Iterator<String> keys=all.keys();keys.hasNext();){String key=keys.next();JSONObject entry=all.optJSONObject(key);if(entry==null||!entry.optString("id").equals(item.optString("id")))continue;if(entry.optBoolean("imported")){for(Book book:Store.load(a))if(book.uri.equals(entry.optString("uri"))){a.open(book);return;}}else if(!entry.has("error"))try(Cursor cursor=a.getSystemService(DownloadManager.class).query(new DownloadManager.Query().setFilterById(Long.parseLong(key)))){if(cursor!=null&&cursor.moveToFirst()&&cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS))!=DownloadManager.STATUS_FAILED){a.startActivity(new Intent(a,DownloadsActivity.class));return;}}catch(Exception ignored){}}
  new AppDialog.Builder(a).setTitle("Download "+(item.optString("kind").equals("Audio")?"audiobook":"ebook")).setMessage(item.optString("title")+"\n\n"+(item.optLong("bytes")>0?android.text.format.Formatter.formatShortFileSize(a,item.optLong("bytes"))+"\n":"")+"Download from "+(item.optString("kind").equals("Audio")?"LibriVox via Internet Archive":"Project Gutenberg")+" and add it to My books when complete. Mobile data may be used.").setPositiveButton("Download",(d,n)->{try{enqueue(a,item);a.startActivity(new Intent(a,DownloadsActivity.class));}catch(Exception e){error(a,e.getMessage());}}).setNegativeButton("Cancel",null).show();
 }
 static String safe(String value){return value.replaceAll("[^a-zA-Z0-9._-]","_");}
 static Uri downloadUri(JSONObject item)throws Exception{Uri uri=Uri.parse(item.getString("download"));String host=uri.getHost();if(!"https".equals(uri.getScheme())||host==null||!(host.equals("archive.org")||host.equals("www.gutenberg.org")||host.equals("gutenberg.org"))||uri.getUserInfo()!=null)throw new IOException("Unapproved download source");return uri;}
 static long enqueue(Context c,JSONObject item)throws Exception{Uri uri=downloadUri(item);String id=safe(item.getString("id"));if(id.isEmpty())throw new IOException("Invalid catalog entry");DownloadManager.Request request=new DownloadManager.Request(uri).setTitle(item.getString("title")).setDescription("Clavis catalog download").setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);request.setDestinationInExternalFilesDir(c,Environment.DIRECTORY_DOWNLOADS,"Catalog/"+id+"-"+UUID.randomUUID()+(item.optString("kind").equals("Audio")?".zip":".epub"));long job=c.getSystemService(DownloadManager.class).enqueue(request);record(c,job,new JSONObject(item.toString()).put("imported",false));return job;}
 static void error(MainActivity a,String message){new AppDialog.Builder(a).setTitle("Catalog download").setMessage(message==null?"Could not complete this download":message).setPositiveButton("OK",null).show();}
 static void schedule(Context c){c.getSystemService(JobScheduler.class).schedule(new JobInfo.Builder(JOB,new ComponentName(c,CatalogImportService.class)).setMinimumLatency(0).build());}
 static void finishAll(Context c,AtomicBoolean cancelled){JSONObject all=records(c);for(Iterator<String> keys=all.keys();keys.hasNext()&&!cancelled.get();){String key=keys.next();JSONObject entry=all.optJSONObject(key);if(entry==null||entry.optBoolean("imported")||entry.has("error"))continue;try{long id=Long.parseLong(key);try(Cursor cursor=c.getSystemService(DownloadManager.class).query(new DownloadManager.Query().setFilterById(id))){if(cursor==null||!cursor.moveToFirst()||cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS))!=DownloadManager.STATUS_SUCCESSFUL)continue;Uri uri=Uri.parse(cursor.getString(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_LOCAL_URI)));File file=new File(uri.getPath()),root=c.getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS);if(!"file".equals(uri.getScheme())||root==null||!file.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator))throw new IOException("Download is outside app storage");Book book=importFile(c,entry,file,cancelled);if(records(c).optJSONObject(key)==null)continue;synchronized(Store.class){ArrayList<Book> books=Store.load(c);if(books.stream().noneMatch(b->b.uri.equals(book.uri))){books.add(book);Store.save(c,books);}}entry.put("uri",book.uri).put("imported",true);entry.remove("error");record(c,id,entry);}}catch(Exception e){if(cancelled.get())return;if(records(c).optJSONObject(key)==null)continue;try{entry.put("error",e.getMessage()==null?"Import failed":e.getMessage());record(c,Long.parseLong(key),entry);}catch(Exception ignored){}}}}
 static Book importFile(Context c,JSONObject entry,File file,AtomicBoolean cancelled)throws Exception{
  if(entry.optString("kind").equals("EPUB")){try(ZipFile zip=new ZipFile(file)){if(zip.getEntry("META-INF/container.xml")==null)throw new IOException("Publisher returned an invalid EPUB");}writeRights(new File(file.getParentFile(),file.getName()+".rights.json"),entry);return new Book(Uri.fromFile(file).toString(),entry.getString("title"),"EPUB");}
  File root=new File(c.getFilesDir(),"catalog-audio"),target=new File(root,safe(entry.getString("id")));root.mkdirs();if(!target.isDirectory()){File stage=new File(root,".stage-"+UUID.randomUUID());stage.mkdirs();try{extract(file,stage,cancelled);writeRights(new File(stage,"source-rights.json"),entry);if(!stage.renameTo(target)&&!target.isDirectory())throw new IOException("Could not finish importing audiobook");}finally{clearStage(stage,root);}}
  File[] files=target.listFiles(f->f.isFile()&&audio(f.getName()));if(files==null||files.length==0)throw new IOException("No playable audio files in this recording");Arrays.sort(files,(a,b)->FolderImporter.naturalCompare(a.getName(),b.getName()));Book book=new Book(Uri.fromFile(target).toString(),entry.getString("title"),"Audio");for(File track:files)book.chapters.add(new Book.Chapter(Uri.fromFile(track).toString(),track.getName().replaceFirst("^\\d+_","").replaceFirst("(?i)\\.[^.]+$","")));book.chaptersChecked=true;return book;
 }
 static boolean audio(String name){return name.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|m4a|m4b|ogg|opus|flac|wav)$");}
 static void extract(File archive,File stage,AtomicBoolean cancelled)throws Exception{long total=0;int count=0;try(ZipFile zip=new ZipFile(archive)){ArrayList<ZipEntry> entries=new ArrayList<>();Enumeration<? extends ZipEntry> enumeration=zip.entries();while(enumeration.hasMoreElements()){if(entries.size()>=10000)throw new IOException("Too many archive entries");entries.add(enumeration.nextElement());}entries.sort((a,b)->FolderImporter.naturalCompare(a.getName(),b.getName()));for(ZipEntry entry:entries){String name=entry.getName().replace('\\','/');if(name.startsWith("/")||Arrays.asList(name.split("/")).contains("..")||name.length()>500)throw new IOException("Unsafe archive path");if(entry.isDirectory()||!audio(name))continue;if(++count>2000)throw new IOException("Too many audio files");if(entry.getSize()>MAX_BYTES-total)throw new IOException("Audiobook exceeds the 4 GB import limit");String base=name.substring(name.lastIndexOf('/')+1);File output=new File(stage,String.format(Locale.US,"%04d_",count)+safe(base));try(InputStream in=zip.getInputStream(entry);OutputStream out=new FileOutputStream(output)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){if(cancelled.get()||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Import interrupted");total+=n;if(total>MAX_BYTES)throw new IOException("Audiobook exceeds the 4 GB import limit");out.write(buffer,0,n);}}}if(count==0)throw new IOException("No audio files in the audiobook ZIP");}}
 static void clearStage(File stage,File root)throws IOException{if(!stage.exists())return;if(!stage.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator)||!stage.getName().startsWith(".stage-"))throw new IOException("Invalid staging directory");File[] files=stage.listFiles();if(files!=null)for(File file:files)if(file.isFile())file.delete();stage.delete();}
 static void writeRights(File file,JSONObject entry)throws Exception{try(OutputStream out=new FileOutputStream(file)){out.write(entry.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
 static int render(MainActivity a,LinearLayout parent){JSONObject all=records(a);int count=0;for(Iterator<String> keys=all.keys();keys.hasNext();){String key=keys.next();JSONObject item=all.optJSONObject(key);if(item==null)continue;long id;try{id=Long.parseLong(key);}catch(Exception e){continue;}count++;LinearLayout card=a.column();card.setPadding(a.dp(14),a.dp(12),a.dp(14),a.dp(12));card.setBackground(UiStyle.surface(a,item.optString("kind"),16));card.addView(a.text(item.optString("title"),16,MainActivity.INK,true));String state="Queued";long bytes=0,total=0;int status=0;try(Cursor c=a.getSystemService(DownloadManager.class).query(new DownloadManager.Query().setFilterById(id))){if(c!=null&&c.moveToFirst()){status=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));bytes=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR));total=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES));state=status==DownloadManager.STATUS_RUNNING?"Downloading":status==DownloadManager.STATUS_PAUSED?"Waiting for network":status==DownloadManager.STATUS_FAILED?"Download failed":status==DownloadManager.STATUS_SUCCESSFUL?item.optBoolean("imported")?"Added to My books":"Importing into My books":"Queued";}else state="Download unavailable";}catch(Exception ignored){}card.addView(a.text(item.optString("error",state),12,MainActivity.MUTED,false));ProgressBar progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);AppTheme.tintProgress(progress);progress.setMax(1000);progress.setIndeterminate(total<=0&&status!=DownloadManager.STATUS_SUCCESSFUL&&status!=DownloadManager.STATUS_FAILED);if(total>0)progress.setProgress((int)Math.min(1000,bytes*1000/total));card.addView(progress);if(item.optBoolean("imported"))card.addView(a.button("Open",()->offer(a,item)));else if(item.has("error")){card.addView(a.button("Retry import",()->{item.remove("error");record(a,id,item);schedule(a);}));card.addView(a.button("Download again",()->offer(a,item)));}else if(status==DownloadManager.STATUS_FAILED)card.addView(a.button("Try download again",()->offer(a,item)));else card.addView(a.button("Cancel",()->{a.getSystemService(DownloadManager.class).remove(id);remove(a,id);}));parent.addView(card);a.space(parent,12);if(status==DownloadManager.STATUS_SUCCESSFUL&&!item.optBoolean("imported")&&!item.has("error")&&a.getSystemService(JobScheduler.class).getPendingJob(JOB)==null)schedule(a);}return count;}
 static synchronized void remove(Context c,long id){JSONObject all=records(c);all.remove(Long.toString(id));c.getSharedPreferences("catalog_downloads",0).edit().putString("jobs",all.toString()).apply();}
}
